"""
WAEC Mathematics Part 3: Lessons l16 to l19 (4 lessons x 14 items = 56 items)
Completes the full 266-item WAEC SSCE Bank.
"""

from scripts.authentic_generators.common import make_opt, make_choices, make_item

COURSE = "waec-ssce-mathematics-mastery"

def get_waec_part3_items():
    items = []

    def add(mod_id, les_id, top_id, obj_text, qs):
        for idx, q in enumerate(qs):
            item_id = f"q_{les_id}_{idx+1}"
            opts = None
            steps = None
            if q["type"] in ["single_choice", "true_false_justification"]:
                opts = make_choices(
                    str(q["correct"]),
                    q["d1"][0], q["d1"][1], q["d1"][2],
                    q["d2"][0], q["d2"][1], q["d2"][2],
                    q["d3"][0], q["d3"][1], q["d3"][2],
                )
            elif q["type"] == "ordering":
                steps = q["steps"]

            items.append(make_item(
                item_id, COURSE, mod_id, les_id, top_id, 0, obj_text,
                q["level"], q["type"], q["prompt"], q["correct"], q["explanation"],
                options=opts, steps=steps
            ))

    # --- l16: Three-Figure Bearings & Angles of Elevation/Depression ---
    add("waec-m6", "l16", "top-waec-trig-03", "Calculate three-figure bearings and angles of elevation and depression", [
        {"level": "understanding", "type": "single_choice", "prompt": "How are three-figure bearings always measured?", "correct": "Clockwise from the True North line, expressed as a three-digit angle ($000^\\circ$ to $360^\\circ$).",
         "d1": ("Counter-clockwise from North.", "MIS-BEARING-ANTICLOCKWISE", "Bearings must be measured clockwise from North."), "d2": ("Clockwise or counter-clockwise depending on quadrant.", "MIS-COMPASS-BEARING", "That describes compass bearings (e.g. N30°E), not 3-figure bearings."), "d3": ("From the horizontal East-West axis.", "MIS-HORIZONTAL-AXIS", "Bearings start strictly from North."), "explanation": "Three-figure bearings are measured clockwise from North using 3 digits."},
        {"level": "understanding", "type": "single_choice", "prompt": "If the bearing of point $B$ from point $A$ is $065^\\circ$, what is the back bearing of $A$ from $B$?", "correct": "$245^\\circ$",
         "d1": ("$115^\\circ$", "MIS-SUPPLEMENTARY", "Back bearing rule for θ < 180° is θ + 180°: 65° + 180° = 245°."), "d2": ("$295^\\circ$", "MIS-ARITH-SLIP", "65 + 180 = 245, not 295."), "d3": ("$065^\\circ$", "MIS-EQUAL-BEARING", "Back bearing is in the opposite direction (differing by 180°)."), "explanation": "Since 065° < 180°, Back Bearing = 65° + 180° = 245°."},
        {"level": "understanding", "type": "single_choice", "prompt": "What is the relationship between the angle of elevation of an object from an observer and the angle of depression of the observer from the object?", "correct": "They are equal, because they are alternate interior angles between parallel horizontal lines.",
         "d1": ("They add up to 90°.", "MIS-COMPLEMENTARY", "They are equal alternate interior angles."), "d2": ("They add up to 180°.", "MIS-SUPPLEMENTARY", "Horizontal lines are parallel, so angles are equal."), "d3": ("Angle of depression is always twice angle of elevation.", "MIS-SCALE-SLIP", "Both angles share equal measure."), "explanation": "Horizontal sight lines are parallel, making elevation and depression alternate angles."},
        {"level": "understanding", "type": "true_false_justification", "prompt": "True or False: The three-figure bearing of due South-West is $225^\\circ$.", "correct": "True: South is $180^\\circ$ and West is $270^\\circ$; halfway is $180^\\circ + 45^\\circ = 225^\\circ$.",
         "d1": ("False: South-West is 135°.", "MIS-SE-CONFUSION", "135° is South-East."), "d2": ("False: South-West is 315°.", "MIS-NW-CONFUSION", "315° is North-West."), "d3": ("True: But only in the Southern Hemisphere.", "MIS-HEMISPHERE-CONFUSION", "Bearing reference holds globally."), "explanation": "SW is 180° + 45° = 225°."},
        {"level": "application", "type": "single_choice", "prompt": "A ship sails $12\\text{ km}$ due North, then $16\\text{ km}$ due East. What is the straight-line distance from the starting point?", "correct": "$20\\text{ km}$",
         "d1": ("$28\\text{ km}$", "MIS-LINEAR-SUM", "12 + 16 = 28 is distance walked; straight line is √(12² + 16²) = 20 km."), "d2": ("$24\\text{ km}$", "MIS-ARITH-SLIP", "√(144 + 256) = √400 = 20 km."), "d3": ("$18\\text{ km}$", "MIS-ROUGH-GUESS", "12-16-20 is a multiple of 3-4-5."), "explanation": "d = √(12² + 16²) = √(144 + 256) = √400 = 20 km."},
        {"level": "application", "type": "single_choice", "prompt": "The bearing of town $Y$ from town $X$ is $130^\\circ$. What is the bearing of $X$ from $Y$?", "correct": "$310^\\circ$",
         "d1": ("$050^\\circ$", "MIS-SUPPLEMENTARY", "Back bearing is 130° + 180° = 310°."), "d2": ("$230^\\circ$", "MIS-ADD-100", "Add 180°, not 100°."), "d3": ("$320^\\circ$", "MIS-ARITH-SLIP", "130 + 180 = 310°."), "explanation": "130° + 180° = 310°."},
        {"level": "application", "type": "single_choice", "prompt": "From the top of a cliff $50\\text{ m}$ high, the angle of depression of a boat on the water is $30^\\circ$. How far is the boat from the base of the cliff?", "correct": "$50\\sqrt{3}\\text{ m} \\approx 86.6\\text{ m}$",
         "d1": ("$25\\text{ m}$", "MIS-SIN-CONFUSION", "50 sin 30° = 25 m is half height; distance d = 50 / tan 30° = 50√3 m."), "d2": ("$100\\text{ m}$", "MIS-HYPOTENUSE-SLIP", "100 m is the line of sight distance (hypotenuse)."), "d3": ("$50\\text{ m}$", "MIS-EQUAL-SLIP", "Angle is 30°, not 45°."), "explanation": "tan 30° = 50 / d => d = 50 / tan 30° = 50 / (1/√3) = 50√3 ≈ 86.6 m."},
        {"level": "application", "type": "numeric_entry", "prompt": "Find the back bearing of $040^\\circ$ in degrees.", "correct": 220,
         "explanation": "40 + 180 = 220°."},
        {"level": "application", "type": "ordering", "prompt": "Arrange the steps to find the distance between two points given their bearings and distances from an origin:", "correct": "A",
         "steps": ["Draw North lines at all reference points and sketch the path.", "Calculate the interior angle enclosed between the two bearing lines.", "Apply the Cosine Rule to find the unknown distance opposite the angle.", "Apply the Sine Rule to calculate any required destination bearings."], "explanation": "Standard navigation and triangulation sequence."},
        {"level": "application", "type": "symbolic_entry", "prompt": "Write the back bearing formula for an initial bearing $\\theta$ where $\\theta < 180^\\circ$.", "correct": "theta + 180",
         "explanation": "Back bearing = theta + 180."},
        {"level": "error_analysis", "type": "single_choice", "prompt": "A student measures a bearing by starting from the horizontal East axis and moving counter-clockwise. What was the mistake?", "correct": "Three-figure bearings must start from the vertical North axis and measure in a clockwise direction.",
         "d1": ("Should have started from South.", "MIS-SOUTH-AXIS", "North is the universal reference line."), "d2": ("Should have measured counter-clockwise from North.", "MIS-BEARING-ANTICLOCKWISE", "Bearings strictly turn clockwise."), "d3": ("There is no error.", "MIS-NO-ERROR-CLAIM", "East-counterclockwise is Cartesian angle, not navigation bearing."), "explanation": "Navigation bearings are strictly measured clockwise from True North."},
        {"level": "error_analysis", "type": "single_choice", "prompt": "To find the back bearing of $210^\\circ$, a student added $180^\\circ$ to get $390^\\circ$. What should the student have done?", "correct": "Subtracted $180^\\circ$ because the forward bearing exceeds $180^\\circ$ ($210^\\circ - 180^\\circ = 030^\\circ$).",
         "d1": ("Subtracted 90°.", "MIS-90-SUB", "Must add or subtract 180°."), "d2": ("Added 360°.", "MIS-FULL-CIRCLE", "Bearings remain in [000°, 360°)."), "d3": ("There is no error.", "MIS-NO-ERROR-CLAIM", "390° is outside the valid range [000°, 360°)."), "explanation": "When θ >= 180°, subtract 180°: 210° - 180° = 030°."},
        {"level": "challenge_transfer", "type": "single_choice", "prompt": "A hunter walks $6\\text{ km}$ on a bearing of $060^\\circ$ and then $8\\text{ km}$ on a bearing of $150^\\circ$. What is his straight-line distance from the starting point?", "correct": "$10\\text{ km}$",
         "d1": ("$14\\text{ km}$", "MIS-LINEAR-SUM", "6 + 8 = 14 km is path length; triangle has angle 180° - (150° - 60°) = 90° => √(6² + 8²) = 10 km."), "d2": ("$12\\text{ km}$", "MIS-ARITH-SLIP", "6-8-10 is a right-angled triangle."), "d3": ("$9.5\\text{ km}$", "MIS-ROUGH-GUESS", "d = 10 km exactly."), "explanation": "Interior angle = 180° - 150° + 60° = 90°. d = √(6² + 8²) = √100 = 10 km."},
        {"level": "challenge_transfer", "type": "single_choice", "prompt": "Two observation posts $A$ and $B$ are $100\\text{ m}$ apart on an East-West line. The bearing of a fire $F$ from $A$ is $030^\\circ$ and from $B$ (due East of $A$) is $330^\\circ$. How far is the fire from line $AB$?", "correct": "$50\\sqrt{3}\\text{ m} \\approx 86.6\\text{ m}$",
         "d1": ("$50\\text{ m}$", "MIS-HALF-BASELINE", "50 m is half the baseline."), "d2": ("$100\\text{ m}$", "MIS-EQUAL-SLIP", "Height = 50 tan 60° = 50√3 m."), "d3": ("$75\\text{ m}$", "MIS-ROUGH-GUESS", "50 × 1.732 ≈ 86.6 m."), "explanation": "Base angles inside triangle are 90° - 30° = 60° each (equilateral triangle). Height = 50 tan 60° = 50√3 ≈ 86.6 m."},
    ])

    # --- l17: Grouped Frequency Distributions: Mean & Modal Class ---
    add("waec-m7", "l17", "top-waec-stat-01", "Calculate mean and modal class of grouped frequency distributions", [
        {"level": "understanding", "type": "single_choice", "prompt": "Which formula correctly gives the estimated mean $\\bar{x}$ of a grouped frequency distribution?", "correct": "$\\bar{x} = \\frac{\\sum f x}{\\sum f}$",
         "d1": ("$\\bar{x} = \\frac{\\sum x}{n}$", "MIS-UNGROUPED-FORMULA", "This applies to ungrouped raw data, omitting frequencies."), "d2": ("$\\bar{x} = \\frac{\\sum f}{\\sum x}$", "MIS-INVERTED-FORMULA", "Frequencies belong in the denominator sum."), "d3": ("$\\bar{x} = \\sum f x$", "MIS-DENOM-DROP", "Must divide by total frequency ∑f."), "explanation": "Grouped mean: x̄ = (∑ fx) / (∑ f)."},
        {"level": "understanding", "type": "single_choice", "prompt": "What is the class midpoint (class mark) $x$ of the interval $20 - 29$?", "correct": "$24.5$",
         "d1": ("$25$", "MIS-ARITH-SLIP", "(20 + 29) / 2 = 49 / 2 = 24.5."), "d2": ("$24$", "MIS-ROUND-DOWN", "Cannot truncate 0.5."), "d3": ("$9$", "MIS-WIDTH-SLIP", "9 is class span, not midpoint."), "explanation": "Midpoint = (20 + 29) / 2 = 49 / 2 = 24.5."},
        {"level": "understanding", "type": "single_choice", "prompt": "How is the modal class identified in a grouped frequency table with equal class widths?", "correct": "The class interval having the highest frequency.",
         "d1": ("The class interval located at the physical centre of the table.", "MIS-MEDIAN-CONFUSION", "Physical position does not determine mode."), "d2": ("The class interval with the largest class width.", "MIS-WIDTH-CONFUSION", "Mode depends on frequency."), "d3": ("The class interval containing the cumulative frequency N/2.", "MIS-MEDIAN-CLASS", "N/2 identifies the median class, not modal class."), "explanation": "Modal class = interval with the highest frequency."},
        {"level": "understanding", "type": "true_false_justification", "prompt": "True or False: The class boundaries of the interval $10 - 19$ (with unit integers) are $9.5$ and $19.5$.", "correct": "True: Boundaries extend $0.5$ below the lower limit and $0.5$ above the upper limit.",
         "d1": ("False: Boundaries are 10 and 19.", "MIS-LIMITS-CONFUSION", "10 and 19 are class limits, not boundaries."), "d2": ("False: Boundaries are 10.5 and 18.5.", "MIS-CONTRACTION", "Boundaries expand to eliminate gaps."), "d3": ("True: But only if total frequency is greater than 50.", "MIS-RESTRICTION", "Boundaries depend on data precision, not sample size."), "explanation": "Class boundaries for integer limits are lower - 0.5 and upper + 0.5."},
        {"level": "application", "type": "single_choice", "prompt": "Classes and frequencies: $1 - 5 (f=4), 6 - 10 (f=8), 11 - 15 (f=5), 16 - 20 (f=3)$. Identify the modal class.", "correct": "$6 - 10$",
         "d1": ("$11 - 15$", "MIS-MEDIAN-CONFUSION", "Class 6-10 has the highest frequency (f=8)."), "d2": ("$1 - 5$", "MIS-FIRST-CLASS", "Frequency is 4."), "d3": ("$16 - 20$", "MIS-LAST-CLASS", "Frequency is 3."), "explanation": "Class 6 - 10 has highest frequency f = 8."},
        {"level": "application", "type": "single_choice", "prompt": "Find the total frequency $\\sum f$ for frequencies: $4, 7, 12, 11, 6$.", "correct": "$40$",
         "d1": ("$35$", "MIS-ARITH-SLIP", "4 + 7 + 12 + 11 + 6 = 40."), "d2": ("$45$", "MIS-ARITH-SLIP", "Sum is exactly 40."), "d3": ("$5$", "MIS-CLASS-COUNT", "5 is number of classes, not total frequency."), "explanation": "4 + 7 + 12 + 11 + 6 = 40."},
        {"level": "application", "type": "single_choice", "prompt": "If $\\sum fx = 750$ and $\\sum f = 25$, calculate the estimated mean $\\bar{x}$.", "correct": "$30$",
         "d1": ("$25$", "MIS-DIVISOR-COPY", "750 / 25 = 30."), "d2": ("$35$", "MIS-ARITH-SLIP", "30 × 25 = 750."), "d3": ("$20$", "MIS-ROUGH-GUESS", "x̄ = 30."), "explanation": "x̄ = 750 / 25 = 30."},
        {"level": "application", "type": "numeric_entry", "prompt": "Calculate the class midpoint of interval $50 - 59$.", "correct": 54.5,
         "explanation": "(50 + 59) / 2 = 109 / 2 = 54.5."},
        {"level": "application", "type": "ordering", "prompt": "Arrange the steps to calculate the estimated mean from a grouped frequency table:", "correct": "A",
         "steps": ["Find the class midpoint x for each class interval.", "Multiply each class midpoint by its frequency: fx.", "Sum the fx column to obtain ∑ fx, and sum frequencies for ∑ f.", "Divide ∑ fx by ∑ f to obtain the mean."], "explanation": "Standard grouped mean sequence."},
        {"level": "application", "type": "symbolic_entry", "prompt": "Write the formula for the class midpoint $x$ given lower limit $L$ and upper limit $U$.", "correct": "(L + U)/2",
         "explanation": "Midpoint = (L + U) / 2."},
        {"level": "error_analysis", "type": "single_choice", "prompt": "A student calculates the mean of a grouped table by adding midpoints $x$ and dividing by the number of classes. What was the error?", "correct": "Omitted the frequencies; each midpoint must be weighted by its frequency $f$ before dividing by $\\sum f$.",
         "d1": ("Should have multiplied by 100%.", "MIS-PERCENT-CONFUSION", "Mean is not a percentage."), "d2": ("Should have used upper class boundaries instead of midpoints.", "MIS-BOUNDARY-CONFUSION", "Midpoints are correct, weighting is missing."), "d3": ("There is no error.", "MIS-NO-ERROR-CLAIM", "Unweighted midpoint mean ignores sample distribution."), "explanation": "Frequency weighting ∑ fx / ∑ f is strictly required for grouped data."},
        {"level": "error_analysis", "type": "single_choice", "prompt": "A student stated that the modal class is the interval with the widest class width. What was the misconception?", "correct": "Confused class width with frequency; modal class is determined strictly by the largest frequency count.",
         "d1": ("Modal class has the smallest class width.", "MIS-WIDTH-INVERSION", "Width does not determine mode."), "d2": ("Modal class is the first class.", "MIS-FIRST-CLASS", "Position does not determine mode."), "d3": ("There is no error.", "MIS-NO-ERROR-CLAIM", "Mode depends on frequency."), "explanation": "Mode is the most frequent value/interval."},
        {"level": "challenge_transfer", "type": "single_choice", "prompt": "In a distribution with classes $1-5 (f=2), 6-10 (f=k), 11-15 (f=5)$, the mean is $9.5$. Find the value of $k$.", "correct": "3",
         "d1": ("4", "MIS-ARITH-SLIP", "Midpoints: 3, 8, 13. ∑ fx = 2(3) + 8k + 5(13) = 6 + 8k + 65 = 71 + 8k. ∑ f = 7 + k. (71 + 8k)/(7 + k) = 9.5 => 71 + 8k = 66.5 + 9.5k => 1.5k = 4.5 => k = 3."), "d2": ("2", "MIS-GUESS-SLIP", "k = 3 satisfies the mean equation."), "d3": ("5", "MIS-EQUAL-FREQ", "k = 3."), "explanation": "(71 + 8k) / (7 + k) = 9.5 => 71 + 8k = 66.5 + 9.5k => 1.5k = 4.5 => k = 3."},
        {"level": "challenge_transfer", "type": "single_choice", "prompt": "Using an assumed mean $A = 25$ and coded deviations $d = \\frac{x - 25}{10}$, a student computes $\\sum f = 50$ and $\\sum fd = 15$. Find the actual mean $\\bar{x}$.", "correct": "$28$",
         "d1": ("$26.5$", "MIS-SCALE-OMIT", "Forgot to multiply by class width 10: 25 + (15/50) = 25.3, with ×10 gives 25 + 3 = 28."), "d2": ("$25.3$", "MIS-SCALE-OMIT", "d is coded; must multiply by width 10."), "d3": ("$30$", "MIS-ARITH-SLIP", "x̄ = A + c(∑ fd / ∑ f) = 25 + 10(15/50) = 25 + 3 = 28."), "explanation": "x̄ = A + c(∑ fd / ∑ f) = 25 + 10(15 / 50) = 25 + 3 = 28."},
    ])

