        {"level": "understanding", "type": "true_false_justification", "prompt": "True or False: A cumulative frequency curve always starts at zero and never decreases as it moves from left to right.", "correct": "True: Frequencies are non-negative, so cumulative frequency is monotonically non-decreasing.",
         "d1": ("False: It decreases when frequencies become small.", "MIS-DECREASING-CONFUSION", "Even small positive frequencies increase the cumulative sum."), "d2": ("False: It forms a bell curve that rises and falls.", "MIS-NORMAL-CURVE", "Frequency curves fall, but cumulative curves only rise."), "d3": ("True: But only for symmetrical data.", "MIS-RESTRICTION", "Monotonicity holds for all datasets."), "explanation": "Cumulative frequency is an accumulating sum of non-negative frequencies."},
