        {"level": "application", "type": "single_choice", "prompt": "If the pass mark is $50$ and the cumulative frequency corresponding to mark $50$ on the Ogive is $70$ out of $100$ students, how many students passed?", "correct": "$30\\text{ students}$",
         "d1": ("$70\\text{ students}$", "MIS-BELOW-PASS", "70 students scored at or below 50 (failed)."), "d2": ("$50\\text{ students}$", "MIS-PASS-MARK", "Number passing is 100 - 70 = 30."), "d3": ("$35\\text{ students}$", "MIS-ARITH-SLIP", "100 - 70 = 30 students."), "explanation": "Number scoring above 50 = Total - CF(50) = 100 - 70 = 30 students."},
